const inputJson = $json || {};
const headers = inputJson.headers || {};
const method = inputJson.method || headers['x-forwarded-method'] || 'POST';
const body = inputJson.body || {};
let apiCode = body.ApiCode || '';

if (!headers.authorization && headers.cookie) {
  const m = headers.cookie.match(/(?:^|; )auth_token=([^;]+)/);
  if (m) headers.authorization = 'Bearer ' + m[1];
}

// --- CHỐNG SQL INJECTION ---
if (!/^@[a-zA-Z0-9_]+$/.test(apiCode)) {
  apiCode = '@invalid_code';
}

const requestOrigin = String(headers.origin || headers.Origin || '').replace(/\/$/, '');
const allowedOrigins = new Set(["http://localhost:3000","http://127.0.0.1:3000","https://medtest.bms79.com"]);
const corsOrigin = allowedOrigins.has(requestOrigin) ? requestOrigin : 'https://cors.invalid';
return [{ json: { ...inputJson, headers: headers, body: { ...body, ApiCode: apiCode }, _method: method.toUpperCase(),
  _corsOrigin: corsOrigin } }];

const input = $('Authorize GetConfig').first().json;
const apiCode = String(input.request?.body?.ApiCode || '@invalid_code');
return [{ json: { query: `EXEC dbo.API_GetConfig @ApiCode = '${apiCode.replace(/'/g, "''")}';` } }];

