const authResult = $('Execute Shared Auth Guard (GetConfig)').first().json;
const request = $('Check Method GetConfig').first().json;
const apiCode = String(request.body?.ApiCode || '@invalid_code').toLowerCase();
const granted = new Set((authResult.verifiedIdentity?.capabilities || []).map(value => String(value).trim().toLowerCase()).filter(Boolean));
const readApis = new Set(["@doanh_so","@hoa_don","@hoa_don_chi_tiet","@don_hang","@cham_diem_kh","@cong_no_khach_hang","@cong_no_chi_tiet","@tich_luy","@tuyen_ban_hang","@goi_ydon_hang","@upsell_goi_y","@goi_ydon_thuoc","@danh_sach_tonkho","@tra_cuu_san_pham","@san_pham_trong_tam","@de_xuat_khuyen_mai","@danh_muc","@khach_hang_list","@dashboard_sinh_nhat","@khao_sat360","@danh_sach_cau_hoi_khao_sat","@kiem_tra_khao_sat","@kiem_tra_khao_sat_ngay","@lich_su_khao_sat","@thong_bao","@tim_san_pham_theo_trieu_chung"]);
const mutationPolicy = {"@lap_don_hang":"orders.write","@khach_hang_insert":"customers.write","@san_pham_trong_tam_import":"products.import"};
const requiredCapabilityFor = (apiCode) => readApis.has(apiCode)
  ? 'api.read'
  : (mutationPolicy[apiCode] || null);
const canUse = (apiCode, granted) => {
  const required = requiredCapabilityFor(apiCode);
  if (!required) return false;
  const specific = apiCode.slice(1).replace(/_/g, '.');
  const candidates = [required, required.startsWith('api.read') ? 'api.read.' + specific : required + '.' + specific];
  return candidates.some(capability => granted.has(capability)) || granted.has('*') || granted.has('api:*');
};
return [{ json: {
  ...authResult,
  request,
  catalogAuthorization: { ok: canUse(apiCode, granted), apiCode }
} }];

