const rows = $input.all().map(item => item.json || {});
const metadataRow = rows.find(row => row.ContractVersion) || {};
const filters = rows
  .filter(field => Number(field.IsSystemParam || 0) !== 1 && field.FieldCode && field.FieldCode !== '@Invalid')
  .map(field => ({
    FieldCode: field.FieldCode,
    FieldName: field.FieldName,
    Placeholder: field.Placeholder,
    Required: Number(field.IsRequired || 0) === 1,
    IsRequired: Number(field.IsRequired || 0),
    DataType: field.DataType,
    ControlType: field.ControlType,
    DefaultValue: field.DefaultValue,
    ValidationRule: field.ValidationRule,
    SourceOfTruth: field.SourceOfTruth,
    OrderIndex: field.OrderIndex,
    DataSourceType: field.DataSourceType,
    DataSourceValue: field.DataSourceValue,
    UiTemplate: field.UiTemplate
  }));
return [{ json: {
  filters,
  contract: {
    version: metadataRow.ContractVersion || null,
    checksum: metadataRow.ContractChecksum || null,
    updatedAt: metadataRow.UpdatedAt || null,
    updatedBy: metadataRow.UpdatedBy || null
  }
} }];
